return $input.all().map((item, index) => {
  const read = item.json;
  const create = $("Create configuration").itemMatching(index).json;
  const simulation = $("Run simulation").itemMatching(index).json;
  const inputs = $("Edit Fields").itemMatching(index).json;

  for (const [name, result] of [
    ["Create configuration", create],
    ["Run simulation", simulation],
    ["Read results", read],
  ]) {
    if (result.code !== 0) {
      throw new Error(`${name} failed: ${result.stderr}`);
    }
  }

  const results = JSON.parse(read.stdout);
  const config = JSON.parse(create.stdout);

  if (
    results.flow_count !== 1 ||
    !Array.isArray(results.flows) ||
    results.flows.length !== 1
  ) {
    throw new Error("Expected exactly one flow");
  }

  const p = results.parameters;
  const m = results.mean;
  const flow = results.flows[0];

  if (
    p.ue_gnb_distance_2d_m !== config.ue_distance_2d_m ||
    p.ue_tx_power_dbm !== config.ue_tx_power_dbm ||
    p.data_rate_bps !== config.offered_load_bps
  ) {
    throw new Error(
      "Results do not match the generated configuration"
    );
  }

  return {
    json: {
      experiment_id: inputs.experiment_id,
      n8n_execution_id: String($execution.id),
      data_source: "ns3",

      config_path: config.config_path,
      results_path: config.results_path,
      experiment_dir: config.experiment_dir,

      ue_distance_2d_m: p.ue_gnb_distance_2d_m,
      ue_distance_3d_m: p.ue_gnb_distance_3d_m,
      ue_tx_power_dbm: p.ue_tx_power_dbm,
      offered_load_mbps: p.data_rate_bps / 1000000,
      bandwidth_hz: p.channel_bandwidth_hz,
      numerology: p.numerology,
      tdd_pattern: p.tdd_pattern,
      packet_size_bytes: p.packet_size_bytes,
      rlc_buffer_size_bytes: p.rlc_buffer_size_bytes,
      rng_seed: config.rng_seed,
      rng_run: config.rng_run,

      throughput_mbps: m.throughput_mbps,
      app_goodput_mbps:
        results.application.goodput_over_app_window_mbps,
      end_to_end_delay_ms: m.end_to_end_delay_ms,
      jitter_ms: m.jitter_ms,
      loss_fraction: m.loss_fraction,

      tx_packets: flow.tx_packets,
      rx_packets: flow.rx_packets,
      ip_rx_bytes: flow.ip_rx_bytes,
      unreceived_packets_after_drain:
        flow.unreceived_packets_after_drain
    },
    pairedItem: { item: index }
  };
});

const distances = [50, 100, 150];

return distances.map((distance, index) => ({
  json: {
    experiment_index: index + 1,
    experiment_id: `distance_${distance}m`,
    ue_distance_2d_m: distance,
    ue_tx_power_dbm: 10,
    offered_load_mbps: 20,
    rng_seed: 42,
    rng_run: 1
  },
  pairedItem: { item: 0 }
}));
